+/** Records each operation failure before any aggregation and attempts every distinct owned close once. */
+function settlePreparationStorage<T>(
+  preparation: DependencyPreparation,
+  operation: () => T,
+  originals: readonly PreparationOriginal[],
+): T {
+  const failures: unknown[] = [];
+  let outcome: { value: T } | undefined;
+  try {
+    outcome = { value: operation() };
+  } catch (cause) {
+    recordPreparationFailure(preparation, 'operation', cause);
+    failures.push(cause);
+  }
+  for (const original of originals) {
+    try {
+      closePreparationOriginal(preparation, original);
+    } catch (cause) {
+      failures.push(cause);
+    }
+  }
+  if (failures.length === 1) throw failures[0];
+  if (failures.length > 1) throw new AggregateError(failures, 'private storage outcomes');
+  if (outcome === undefined) throw new Error('storage outcome absent');
+  return outcome.value;
+}
